// MaaAgentClient keeps the same Process returned by its startup
// delegate. Dispose the owner first after the child has exited;
// otherwise its resource-release callback sees a disposed Process.
if (processExited && agentClient != null)
{
    Process? ownedProcess = null;
    try { ownedProcess = agentClient.AgentServerProcess; }
    catch (InvalidOperationException) { /* No process is managed by this client. */ }
    if (ReferenceEquals(ownedProcess, agentProcess))
    {
        try { agentClient.Dispose(); }
        catch (Exception e)
        {
            LoggerHelper.Warning($"释放 AgentClient 失败：{e.Message}");
            processExited = false;
        }
    }
}
try { agentProcess.Dispose(); }
catch (Exception e) { LoggerHelper.Warning($"释放 Agent 进程对象失败：{e.Message}"); }
